def _post_with_urllib(url: str, file_path: str, filename: str, meta: dict, timeout: int = 60):
    from urllib import request

    body_gen, content_type = _build_multipart(file_path, filename, meta)

    class IterableReader:
        def __init__(self, iterable):
            self.iterable = iterable
            self.iterator = iter(iterable)

        def read(self, amt=None):
            try:
                return next(self.iterator)
            except StopIteration:
                return b""

    req = request.Request(url, method="POST")
    req.add_header("Content-Type", content_type)
    # Content-Length omitted intentionally to allow chunked transfer; some servers may not support it.
    # If server requires Content-Length, we would need to buffer; for now assume chunked is fine.

    with request.urlopen(req, data=IterableReader(body_gen), timeout=timeout) as resp:
        return resp.read(), resp.status

